-- ============================================================================
-- Orange Taxi — Audit remediation, part 2 (2026-10-25)
-- Requires 20261025120000_audit_remediation.sql. Idempotent. NOT YET APPLIED.
-- Verified with scripts/db-tests (PGlite).
--
--   S1  Schema drift: columns/tables the apps use but no migration created.
--   S2  Server-authoritative fares: distance bounded by the trip's coordinates,
--       tariff from vehicle_categories/pricing_settings, hourly packages, and
--       one-time promo redemption (promo_redemptions). Ride OTP generated by the
--       server.
--   S3  Driver may not raise final_fare above the booked fare.
--   S4  Wallet rides settle automatically when completed (covers offline
--       completions); deduct_ride_wallet_payment shares the same logic.
--   S5  Scheduled rides: claim / release / start RPCs (the clients' direct updates
--       were rejected by the integrity trigger). Drivers can no longer unassign
--       themselves from a live ride (NULL-safe driver_id check).
--   S6  get_ride_otp() / get_assigned_driver(): the narrow reads the apps need.
--       (supabase/deferred/ removes the broad column access once apps update.)
--   S7  admin_link_driver(): links an approved driver row to the auth account
--       by email (the admin panel looked up profiles.email, which never existed,
--       so user_id was never set and drivers could not sign in).
--   S8  credit_wallet_topup(): service-role-only wallet credit used after a
--       verified Razorpay payment.
--   S9  Realtime chat: private channels limited to the ride's passenger/driver.
--   S10 Storage: drivers and their passengers can read the driver's photo;
--       drivers can read their own KYC files (signed URLs).
--   S11 fleet_vehicles (used by the admin fleet manager, never created; it ran
--       on browser-local demo data). Admin-only.
-- ============================================================================

-- S1 ---------------------------------------------------------------------------
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS wallet_balance numeric NOT NULL DEFAULT 0;
DO $$ BEGIN
  ALTER TABLE public.profiles ADD CONSTRAINT profiles_wallet_non_negative CHECK (wallet_balance >= 0);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;
ALTER TABLE public.drivers ADD COLUMN IF NOT EXISTS driver_type text NOT NULL DEFAULT 'company';
ALTER TABLE public.bookings ADD COLUMN IF NOT EXISTS safety_status text;
ALTER TABLE public.bookings ADD COLUMN IF NOT EXISTS ride_type text NOT NULL DEFAULT 'point_to_point';
ALTER TABLE public.bookings ADD COLUMN IF NOT EXISTS rental_hours int;
ALTER TABLE public.bookings ADD COLUMN IF NOT EXISTS promo_code text;
ALTER TABLE public.bookings ADD COLUMN IF NOT EXISTS discount_amount numeric NOT NULL DEFAULT 0;

CREATE TABLE IF NOT EXISTS public.sos_alerts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  booking_id uuid REFERENCES public.bookings(id) ON DELETE SET NULL,
  user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  driver_id uuid REFERENCES public.drivers(id) ON DELETE SET NULL,
  guardian_phone text,
  pickup_area text,
  drop_area text,
  status text NOT NULL DEFAULT 'triggered',
  triggered_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.sos_alerts ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "sos_insert_own" ON public.sos_alerts;
CREATE POLICY "sos_insert_own" ON public.sos_alerts FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid());
DROP POLICY IF EXISTS "sos_read_own_or_admin" ON public.sos_alerts;
CREATE POLICY "sos_read_own_or_admin" ON public.sos_alerts FOR SELECT TO authenticated
  USING (user_id = auth.uid() OR public.has_role(auth.uid(), 'admin'));
DROP POLICY IF EXISTS "sos_admin_update" ON public.sos_alerts;
CREATE POLICY "sos_admin_update" ON public.sos_alerts FOR UPDATE TO authenticated
  USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));

CREATE TABLE IF NOT EXISTS public.promo_redemptions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  code text NOT NULL,
  booking_id uuid REFERENCES public.bookings(id) ON DELETE CASCADE,
  discount numeric NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (user_id, code)
);
ALTER TABLE public.promo_redemptions ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "promo_read_own" ON public.promo_redemptions;
CREATE POLICY "promo_read_own" ON public.promo_redemptions FOR SELECT TO authenticated
  USING (user_id = auth.uid() OR public.has_role(auth.uid(), 'admin'));
-- No client insert/update/delete policies: rows are written by triggers only.

-- S2 ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_km_between(lat1 double precision, lng1 double precision, lat2 double precision, lng2 double precision)
RETURNS double precision LANGUAGE sql IMMUTABLE AS $$
  SELECT 6371 * 2 * asin(sqrt(
    power(sin(radians(lat2 - lat1) / 2), 2) +
    cos(radians(lat1)) * cos(radians(lat2)) * power(sin(radians(lng2 - lng1) / 2), 2)))
$$;

-- "lat,lng" -> point (NULL when unparsable or out of range)
CREATE OR REPLACE FUNCTION public.fn_parse_coord(raw text)
RETURNS point LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE parts text[]; la double precision; lo double precision;
BEGIN
  IF raw IS NULL THEN RETURN NULL; END IF;
  parts := string_to_array(trim(raw), ',');
  IF array_length(parts, 1) <> 2 THEN RETURN NULL; END IF;
  BEGIN
    la := trim(parts[1])::double precision;
    lo := trim(parts[2])::double precision;
  EXCEPTION WHEN OTHERS THEN RETURN NULL; END;
  IF la < -90 OR la > 90 OR lo < -180 OR lo > 180 THEN RETURN NULL; END IF;
  RETURN point(la, lo);
END; $$;

-- Straight-line length of pickup -> (stop ->) drop, from the booking's coordinate strings.
CREATE OR REPLACE FUNCTION public.fn_trip_straight_km(pickup_address text, drop_address text)
RETURNS double precision LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE p point; segs text[]; total double precision := 0; prev point; cur point; s text;
BEGIN
  p := public.fn_parse_coord(split_part(COALESCE(pickup_address, ''), '|', 1));
  IF p IS NULL OR drop_address IS NULL THEN RETURN NULL; END IF;
  prev := p;
  segs := string_to_array(drop_address, '|');
  FOREACH s IN ARRAY segs LOOP
    cur := public.fn_parse_coord(s);
    IF cur IS NULL THEN RETURN NULL; END IF;
    total := total + public.fn_km_between(prev[0], prev[1], cur[0], cur[1]);
    prev := cur;
  END LOOP;
  RETURN total;
END; $$;

-- Hourly rental packages (must match HourlyRentalModal in the rider app).
CREATE OR REPLACE FUNCTION public.fn_hourly_package_price(_hours int)
RETURNS numeric LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE _hours WHEN 1 THEN 360 WHEN 2 THEN 648 WHEN 3 THEN 972 WHEN 4 THEN 1296 WHEN 5 THEN 1620
                     WHEN 6 THEN 1944 WHEN 8 THEN 2592 WHEN 10 THEN 3240 WHEN 12 THEN 3888 END::numeric
$$;

CREATE OR REPLACE FUNCTION public.check_booking_insert_integrity()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  is_trusted boolean := public.has_role(auth.uid(), 'admin') OR auth.role() = 'service_role';
  v_base numeric := 99; v_per_km numeric := 18; v_min numeric := 149;
  v_tax_pct numeric := 0; v_platform numeric := 0;
  v_cat record; v_set record;
  straight double precision;
  dist numeric;
  pre_tax numeric;
  floor_fare numeric;
  pkg numeric;
  promo_disc numeric := 0;
BEGIN
  IF auth.uid() IS NOT NULL AND auth.role() <> 'service_role' THEN
    NEW.customer_id := auth.uid();
  END IF;

  IF is_trusted THEN
    RETURN NEW;
  END IF;

  NEW.status := CASE WHEN NEW.scheduled_at IS NOT NULL THEN 'scheduled' ELSE 'searching' END;
  NEW.driver_id := NULL;
  NEW.final_fare := NULL;
  NEW.started_at := NULL; NEW.completed_at := NULL; NEW.accepted_at := NULL; NEW.arrived_at := NULL;
  NEW.payment_status := 'pending';
  NEW.payment_made := 'no';
  NEW.discount_amount := 0;
  -- Ride OTP comes from the server, never from the client.
  NEW.ride_otp := lpad((floor(random() * 10000))::int::text, 4, '0');

  SELECT base_fare, per_km, minimum_fare INTO v_cat
  FROM public.vehicle_categories WHERE code = NEW.vehicle_code AND is_active = true LIMIT 1;
  IF FOUND THEN v_base := v_cat.base_fare; v_per_km := v_cat.per_km; v_min := v_cat.minimum_fare; END IF;
  SELECT tax_percent, platform_fee INTO v_set FROM public.pricing_settings WHERE id = 1;
  IF FOUND THEN v_tax_pct := COALESCE(v_set.tax_percent, 0); v_platform := COALESCE(v_set.platform_fee, 0); END IF;

  IF NEW.ride_type = 'hourly' THEN
    pkg := public.fn_hourly_package_price(NEW.rental_hours);
    IF pkg IS NULL THEN
      RAISE EXCEPTION 'Unknown hourly rental package.';
    END IF;
    NEW.distance_km := NEW.rental_hours * 10;
    NEW.duration_min := NEW.rental_hours * 60;
    floor_fare := pkg;
  ELSE
    NEW.ride_type := 'point_to_point';
    NEW.rental_hours := NULL;
    -- Distance can't be shorter than the straight line between the trip's own coordinates (+15% for roads).
    straight := public.fn_trip_straight_km(NEW.pickup_address, NEW.drop_address);
    dist := GREATEST(COALESCE(NEW.distance_km, 0), COALESCE(straight * 1.15, 0));
    NEW.distance_km := ROUND(dist, 1);
    pre_tax := GREATEST(v_min, v_base + ROUND(dist * v_per_km));
    -- Same rounding as the web app's calcFare(): round(raw + round(raw*tax%) + round(platform)).
    floor_fare := pre_tax + ROUND(pre_tax * v_tax_pct / 100.0) + ROUND(v_platform);

    -- One-time promo, validated and recorded here.
    IF NEW.promo_code IS NOT NULL THEN
      NEW.promo_code := upper(trim(NEW.promo_code));
      IF NEW.promo_code = 'FIRST100'
         AND floor_fare >= 180
         AND NOT EXISTS (SELECT 1 FROM public.promo_redemptions WHERE user_id = NEW.customer_id AND code = 'FIRST100') THEN
        promo_disc := LEAST(100, floor_fare - v_min);
      ELSE
        NEW.promo_code := NULL;
      END IF;
    END IF;
    floor_fare := floor_fare - promo_disc;
  END IF;

  IF COALESCE(NEW.estimated_fare, 0) < floor_fare THEN
    NEW.estimated_fare := floor_fare;
    NEW.base_fare := CASE WHEN NEW.ride_type = 'hourly' THEN floor_fare ELSE v_base END;
    NEW.distance_fare := CASE WHEN NEW.ride_type = 'hourly' THEN 0 ELSE ROUND(dist * v_per_km) END;
    NEW.tax_amount := CASE WHEN NEW.ride_type = 'hourly' THEN 0 ELSE ROUND(pre_tax * v_tax_pct / 100.0) END;
  END IF;
  NEW.discount_amount := promo_disc;
  RETURN NEW;
END;
$$;

-- Recorded after the booking row exists (FK). A concurrent second redemption fails on UNIQUE(user_id, code).
CREATE OR REPLACE FUNCTION public.record_promo_redemption()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NEW.promo_code IS NOT NULL AND NEW.discount_amount > 0 THEN
    INSERT INTO public.promo_redemptions (user_id, code, booking_id, discount)
    VALUES (NEW.customer_id, NEW.promo_code, NEW.id, NEW.discount_amount);
  END IF;
  RETURN NEW;
END; $$;
DROP TRIGGER IF EXISTS trg_record_promo_redemption ON public.bookings;
CREATE TRIGGER trg_record_promo_redemption AFTER INSERT ON public.bookings
  FOR EACH ROW EXECUTE FUNCTION public.record_promo_redemption();

-- S3 + S5: booking update rules (from part 1) plus final_fare cap and the scheduled-claim path.
CREATE OR REPLACE FUNCTION public.check_booking_update_integrity()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  is_admin boolean := public.has_role(auth.uid(), 'admin');
  is_assigned_driver boolean := public.is_driver_of(OLD.driver_id, auth.uid());
BEGIN
  IF is_admin OR auth.role() = 'service_role' THEN
    RETURN NEW;
  END IF;

  IF current_setting('app.wallet_settlement', true) = 'on' THEN
    IF (to_jsonb(NEW) - ARRAY['payment_status', 'payment_made', 'updated_at'])
       IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['payment_status', 'payment_made', 'updated_at']) THEN
      RAISE EXCEPTION 'Security Violation: wallet settlement may only change payment fields.';
    END IF;
    RETURN NEW;
  END IF;

  IF current_setting('app.scheduled_claim', true) = 'on' THEN
    IF (to_jsonb(NEW) - ARRAY['driver_id', 'updated_at']) IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['driver_id', 'updated_at']) THEN
      RAISE EXCEPTION 'Security Violation: scheduled claim may only set the driver.';
    END IF;
    RETURN NEW;
  END IF;

  IF current_setting('app.scheduled_start', true) = 'on' THEN
    IF (to_jsonb(NEW) - ARRAY['status', 'accepted_at', 'updated_at']) IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['status', 'accepted_at', 'updated_at'])
       OR NEW.status <> 'accepted' THEN
      RAISE EXCEPTION 'Security Violation: starting a scheduled ride may only accept it.';
    END IF;
    RETURN NEW;
  END IF;

  IF auth.uid() = OLD.customer_id THEN
    IF NEW.estimated_fare <> OLD.estimated_fare OR
       NEW.base_fare <> OLD.base_fare OR
       NEW.distance_fare <> OLD.distance_fare OR
       NEW.tax_amount <> OLD.tax_amount OR
       NEW.final_fare IS DISTINCT FROM OLD.final_fare OR
       NEW.discount_amount IS DISTINCT FROM OLD.discount_amount OR
       NEW.promo_code IS DISTINCT FROM OLD.promo_code OR
       NEW.ride_otp IS DISTINCT FROM OLD.ride_otp OR
       NEW.distance_km IS DISTINCT FROM OLD.distance_km OR
       NEW.payment_status <> OLD.payment_status OR
       NEW.payment_made IS DISTINCT FROM OLD.payment_made OR
       NEW.payment_method IS DISTINCT FROM OLD.payment_method OR
       NEW.customer_id <> OLD.customer_id OR
       NEW.driver_id IS DISTINCT FROM OLD.driver_id THEN
      RAISE EXCEPTION 'Security Violation: Unauthorized customer modification of financial, payment, or dispatch fields.';
    END IF;

    IF NEW.status <> OLD.status THEN
      IF NEW.status = 'cancelled' THEN
        IF OLD.status NOT IN ('searching', 'scheduled', 'accepted') THEN
          RAISE EXCEPTION 'Cancellation denied: Ride is already arrived or in-progress.';
        END IF;
      ELSE
        RAISE EXCEPTION 'Security Violation: Illegal ride status transition requested by passenger.';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  IF is_assigned_driver THEN
    IF NEW.estimated_fare <> OLD.estimated_fare OR
       NEW.base_fare <> OLD.base_fare OR
       NEW.distance_fare <> OLD.distance_fare OR
       NEW.tax_amount <> OLD.tax_amount OR
       NEW.discount_amount IS DISTINCT FROM OLD.discount_amount OR
       NEW.promo_code IS DISTINCT FROM OLD.promo_code OR
       (NEW.ride_otp IS DISTINCT FROM OLD.ride_otp AND current_setting('app.otp_verified', true) IS DISTINCT FROM 'on') OR
       NEW.customer_id <> OLD.customer_id OR
       NEW.driver_id IS DISTINCT FROM OLD.driver_id THEN
      RAISE EXCEPTION 'Security Violation: Chauffeurs cannot alter commercial pricing, passenger ownership, or reassign trips.';
    END IF;

    IF NEW.final_fare IS DISTINCT FROM OLD.final_fare
       AND (NEW.final_fare IS NULL OR NEW.final_fare < 0 OR NEW.final_fare > OLD.estimated_fare) THEN
      RAISE EXCEPTION 'Security Violation: Final fare must be between 0 and the booked fare.';
    END IF;

    IF NEW.status <> OLD.status THEN
      IF OLD.status = 'accepted' AND NEW.status NOT IN ('arrived', 'cancelled') THEN
        RAISE EXCEPTION 'Invalid status transition: Accepted ride can only transition to arrived or cancelled.';
      ELSIF OLD.status = 'arrived' AND NEW.status = 'in_progress' THEN
        IF current_setting('app.otp_verified', true) IS DISTINCT FROM 'on' THEN
          RAISE EXCEPTION 'Invalid status transition: Arrived ride can only transition to in_progress via OTP verification (verify_ride_otp).';
        END IF;
      ELSIF OLD.status = 'arrived' AND NEW.status NOT IN ('in_progress', 'cancelled') THEN
        RAISE EXCEPTION 'Invalid status transition: Arrived ride can only transition to in_progress (via OTP) or cancelled.';
      ELSIF OLD.status = 'in_progress' AND NEW.status NOT IN ('completed') THEN
        RAISE EXCEPTION 'Invalid status transition: In-progress ride can only transition to completed.';
      ELSIF OLD.status IN ('completed', 'cancelled', 'scheduled') THEN
        RAISE EXCEPTION 'Invalid status transition: This ride cannot change status from %.', OLD.status;
      END IF;
    END IF;

    IF NEW.payment_status <> OLD.payment_status
       AND NEW.payment_status = 'paid'
       AND NEW.payment_method NOT IN ('cash', 'driver_upi') THEN
      RAISE EXCEPTION 'Security Violation: Online gateway payments must be verified by payment gateway settlement.';
    END IF;
    RETURN NEW;
  END IF;

  IF OLD.status = 'searching' AND OLD.driver_id IS NULL
     AND NEW.status = 'accepted'
     AND NEW.driver_id = public.current_active_driver_id() THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'Security Violation: Unauthorized booking modification.';
END;
$$;

-- Release a promo when the ride is cancelled so the passenger can use it again.
CREATE OR REPLACE FUNCTION public.release_promo_on_cancel()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NEW.status = 'cancelled' AND OLD.status <> 'cancelled' AND NEW.promo_code IS NOT NULL THEN
    DELETE FROM public.promo_redemptions WHERE booking_id = NEW.id;
  END IF;
  RETURN NEW;
END; $$;
DROP TRIGGER IF EXISTS trg_release_promo_on_cancel ON public.bookings;
CREATE TRIGGER trg_release_promo_on_cancel AFTER UPDATE OF status ON public.bookings
  FOR EACH ROW EXECUTE FUNCTION public.release_promo_on_cancel();

-- S4 ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.settle_wallet_booking_internal(_booking_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE b record; bal numeric; amt numeric;
BEGIN
  SELECT id, customer_id, status, payment_method, payment_status, final_fare, estimated_fare
  INTO b FROM public.bookings WHERE id = _booking_id FOR UPDATE;
  IF b.id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Booking record not found.'); END IF;
  IF b.payment_method <> 'wallet' THEN RETURN jsonb_build_object('success', false, 'error', 'Booking payment method is not wallet.'); END IF;
  IF b.status NOT IN ('in_progress', 'completed') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Ride must be in progress or completed to settle fare.');
  END IF;
  IF b.payment_status = 'paid' THEN RETURN jsonb_build_object('success', true, 'message', 'Payment already settled.'); END IF;

  amt := ROUND(COALESCE(b.final_fare, b.estimated_fare, 0), 2);
  SELECT COALESCE(wallet_balance, 0) INTO bal FROM public.profiles WHERE id = b.customer_id FOR UPDATE;
  IF bal < amt THEN
    RETURN jsonb_build_object('success', false, 'error', 'Insufficient customer wallet balance. Please collect cash or alternate UPI.');
  END IF;

  PERFORM set_config('app.allow_wallet_mutation', 'on', true);
  UPDATE public.profiles SET wallet_balance = bal - amt, updated_at = now() WHERE id = b.customer_id;
  PERFORM set_config('app.allow_wallet_mutation', 'off', true);
  INSERT INTO public.wallet_transactions (user_id, amount, type, description, booking_id)
  VALUES (b.customer_id, amt, 'debit', 'Fare payment for Ride #' || b.id, b.id);
  PERFORM set_config('app.wallet_settlement', 'on', true);
  UPDATE public.bookings SET payment_status = 'paid', payment_made = 'yes', updated_at = now() WHERE id = b.id;
  PERFORM set_config('app.wallet_settlement', 'off', true);
  RETURN jsonb_build_object('success', true, 'amount_deducted', amt, 'remaining_balance', bal - amt);
END; $$;
REVOKE ALL ON FUNCTION public.settle_wallet_booking_internal(uuid) FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.deduct_ride_wallet_payment(_booking_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE b record;
BEGIN
  IF auth.uid() IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Authentication required.'); END IF;
  SELECT id, customer_id, driver_id INTO b FROM public.bookings WHERE id = _booking_id;
  IF b.id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Booking record not found.'); END IF;
  IF NOT (public.is_driver_of(b.driver_id, auth.uid()) OR b.customer_id = auth.uid() OR public.has_role(auth.uid(), 'admin')) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Unauthorized: You cannot settle this ride.');
  END IF;
  RETURN public.settle_wallet_booking_internal(_booking_id);
END; $$;
GRANT EXECUTE ON FUNCTION public.deduct_ride_wallet_payment(uuid) TO authenticated;

CREATE OR REPLACE FUNCTION public.auto_settle_wallet_on_complete()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NEW.status = 'completed' AND OLD.status <> 'completed'
     AND NEW.payment_method = 'wallet' AND NEW.payment_status <> 'paid' THEN
    PERFORM public.settle_wallet_booking_internal(NEW.id); -- insufficient balance leaves it pending
  END IF;
  RETURN NEW;
END; $$;
DROP TRIGGER IF EXISTS trg_auto_settle_wallet ON public.bookings;
CREATE TRIGGER trg_auto_settle_wallet AFTER UPDATE OF status ON public.bookings
  FOR EACH ROW EXECUTE FUNCTION public.auto_settle_wallet_on_complete();

-- S5 ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.claim_scheduled_booking(_booking_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE drv uuid := public.current_active_driver_id(); claimed record;
BEGIN
  IF drv IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Your chauffeur account is not active.'); END IF;
  PERFORM set_config('app.scheduled_claim', 'on', true);
  UPDATE public.bookings SET driver_id = drv, updated_at = now()
  WHERE id = _booking_id AND status = 'scheduled' AND driver_id IS NULL
  RETURNING id, reference, scheduled_at, pickup_area, drop_area INTO claimed;
  PERFORM set_config('app.scheduled_claim', 'off', true);
  IF claimed.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Another chauffeur already claimed this departure.');
  END IF;
  RETURN jsonb_build_object('success', true, 'booking', row_to_json(claimed));
END; $$;
REVOKE ALL ON FUNCTION public.claim_scheduled_booking(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.claim_scheduled_booking(uuid) TO authenticated;

CREATE OR REPLACE FUNCTION public.release_scheduled_booking(_booking_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE drv uuid := public.current_active_driver_id(); rel uuid;
BEGIN
  IF drv IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Your chauffeur account is not active.'); END IF;
  PERFORM set_config('app.scheduled_claim', 'on', true);
  UPDATE public.bookings SET driver_id = NULL, updated_at = now()
  WHERE id = _booking_id AND status = 'scheduled' AND driver_id = drv
  RETURNING id INTO rel;
  PERFORM set_config('app.scheduled_claim', 'off', true);
  IF rel IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'This scheduled ride is not assigned to you.'); END IF;
  RETURN jsonb_build_object('success', true);
END; $$;
REVOKE ALL ON FUNCTION public.release_scheduled_booking(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.release_scheduled_booking(uuid) TO authenticated;

-- Lets the assigned chauffeur start a claimed scheduled ride up to 60 minutes before pickup.
CREATE OR REPLACE FUNCTION public.start_scheduled_booking(_booking_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE drv uuid := public.current_active_driver_id(); started record;
BEGIN
  IF drv IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Your chauffeur account is not active.'); END IF;
  IF EXISTS (SELECT 1 FROM public.bookings WHERE driver_id = drv AND status IN ('accepted', 'arrived', 'in_progress')) THEN
    RETURN jsonb_build_object('success', false, 'error', 'You already have an active ride in progress.');
  END IF;
  PERFORM set_config('app.scheduled_start', 'on', true);
  UPDATE public.bookings SET status = 'accepted', accepted_at = now(), updated_at = now()
  WHERE id = _booking_id AND status = 'scheduled' AND driver_id = drv
    AND scheduled_at <= now() + interval '60 minutes'
  RETURNING * INTO started;
  PERFORM set_config('app.scheduled_start', 'off', true);
  IF started.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'This ride is not assigned to you or is more than 60 minutes away.');
  END IF;
  RETURN jsonb_build_object('success', true, 'booking', row_to_json(started));
END; $$;
REVOKE ALL ON FUNCTION public.start_scheduled_booking(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.start_scheduled_booking(uuid) TO authenticated;

-- Drivers can list open scheduled rides and the ones they claimed.
DROP POLICY IF EXISTS "bookings_select_driver" ON public.bookings;
CREATE POLICY "bookings_select_driver" ON public.bookings
  FOR SELECT TO authenticated
  USING (
    (status IN ('searching', 'scheduled') AND driver_id IS NULL AND public.current_active_driver_id() IS NOT NULL)
    OR public.is_driver_of(driver_id, auth.uid())
  );

-- S6 ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.get_ride_otp(_booking_id uuid)
RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT ride_otp FROM public.bookings
  WHERE id = _booking_id AND customer_id = auth.uid()
    AND status IN ('searching', 'scheduled', 'accepted', 'arrived')
$$;
REVOKE ALL ON FUNCTION public.get_ride_otp(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_ride_otp(uuid) TO authenticated;

CREATE OR REPLACE FUNCTION public.get_assigned_driver(_booking_id uuid)
RETURNS TABLE (
  id uuid, full_name text, phone text, photo_url text, vehicle_model text, vehicle_number text,
  vehicle_code text, rating numeric, total_rides int, current_lat double precision,
  current_lng double precision, location_updated_at timestamptz
)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT d.id, d.full_name, d.phone, d.photo_url, d.vehicle_model, d.vehicle_number, d.vehicle_code,
         d.rating, d.total_rides, d.current_lat::double precision, d.current_lng::double precision, d.location_updated_at
  FROM public.bookings b JOIN public.drivers d ON d.id = b.driver_id
  WHERE b.id = _booking_id AND b.customer_id = auth.uid()
    AND b.status IN ('accepted', 'arrived', 'in_progress', 'completed')
$$;
REVOKE ALL ON FUNCTION public.get_assigned_driver(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_assigned_driver(uuid) TO authenticated;

-- S7 ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.admin_link_driver(_driver_id uuid, _email text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth AS $$
DECLARE target uuid; existing uuid;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RETURN jsonb_build_object('success', false, 'error', 'forbidden');
  END IF;
  SELECT id INTO target FROM auth.users WHERE lower(email) = lower(trim(_email)) LIMIT 1;
  IF target IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No account with that email has signed up yet.');
  END IF;
  SELECT id INTO existing FROM public.drivers WHERE user_id = target AND id <> _driver_id;
  IF existing IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'That account is already linked to another driver record.');
  END IF;
  UPDATE public.drivers SET user_id = target, updated_at = now() WHERE id = _driver_id;
  INSERT INTO public.user_roles (user_id, role) VALUES (target, 'driver') ON CONFLICT DO NOTHING;
  RETURN jsonb_build_object('success', true, 'user_id', target);
END; $$;
REVOKE ALL ON FUNCTION public.admin_link_driver(uuid, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_link_driver(uuid, text) TO authenticated;

-- S8 ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.credit_wallet_topup(_user_id uuid, _amount numeric, _payment_id text, _description text DEFAULT 'Wallet top-up')
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE amt numeric := ROUND(COALESCE(_amount, 0), 2); bal numeric;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Only the payment server can credit wallets.');
  END IF;
  IF amt <= 0 OR amt > 25000 THEN RETURN jsonb_build_object('success', false, 'error', 'Invalid amount.'); END IF;
  IF _payment_id IS NULL OR trim(_payment_id) = '' THEN RETURN jsonb_build_object('success', false, 'error', 'Payment id required.'); END IF;
  IF EXISTS (SELECT 1 FROM public.wallet_transactions WHERE reference_id = trim(_payment_id)) THEN
    SELECT wallet_balance INTO bal FROM public.profiles WHERE id = _user_id;
    RETURN jsonb_build_object('success', true, 'already_credited', true, 'new_balance', bal);
  END IF;
  SELECT COALESCE(wallet_balance, 0) INTO bal FROM public.profiles WHERE id = _user_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'User profile not found.'); END IF;
  UPDATE public.profiles SET wallet_balance = bal + amt, updated_at = now() WHERE id = _user_id;
  INSERT INTO public.wallet_transactions (user_id, amount, type, description, reference_id)
  VALUES (_user_id, amt, 'credit', _description, trim(_payment_id));
  RETURN jsonb_build_object('success', true, 'new_balance', bal + amt, 'amount_credited', amt);
END; $$;
REVOKE ALL ON FUNCTION public.credit_wallet_topup(uuid, numeric, text, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.credit_wallet_topup(uuid, numeric, text, text) TO service_role;
DO $$ BEGIN
  CREATE UNIQUE INDEX IF NOT EXISTS wallet_transactions_reference_unique
    ON public.wallet_transactions (reference_id) WHERE reference_id IS NOT NULL;
EXCEPTION WHEN unique_violation THEN
  RAISE NOTICE 'Duplicate wallet reference ids exist; unique index not created. Clean them up and re-run.';
END $$;

-- S9 ---------------------------------------------------------------------------
-- Private Realtime channels: topic "ride-chat-<booking uuid>", members = passenger + assigned driver.
-- Also turn OFF "Allow public access" for Realtime in the Supabase dashboard after the apps update.
CREATE OR REPLACE FUNCTION public.can_access_ride_channel(_topic text)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE bid uuid;
BEGIN
  IF _topic IS NULL OR _topic NOT LIKE 'ride-chat-%' THEN RETURN false; END IF;
  BEGIN bid := substring(_topic from 11)::uuid; EXCEPTION WHEN OTHERS THEN RETURN false; END;
  RETURN EXISTS (
    SELECT 1 FROM public.bookings b
    WHERE b.id = bid AND (b.customer_id = auth.uid() OR public.is_driver_of(b.driver_id, auth.uid()))
  );
END; $$;
REVOKE ALL ON FUNCTION public.can_access_ride_channel(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.can_access_ride_channel(text) TO authenticated;

DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = 'realtime')
     AND to_regclass('realtime.messages') IS NOT NULL THEN
    EXECUTE 'DROP POLICY IF EXISTS "ride_chat_read" ON realtime.messages';
    EXECUTE 'CREATE POLICY "ride_chat_read" ON realtime.messages FOR SELECT TO authenticated
             USING (public.can_access_ride_channel(realtime.topic()))';
    EXECUTE 'DROP POLICY IF EXISTS "ride_chat_write" ON realtime.messages';
    EXECUTE 'CREATE POLICY "ride_chat_write" ON realtime.messages FOR INSERT TO authenticated
             WITH CHECK (public.can_access_ride_channel(realtime.topic()))';
  END IF;
END $$;

-- S10 --------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.can_read_driver_file(_name text)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.drivers d
    WHERE (
      d.user_id = auth.uid()
      AND ('storage://driver_kyc/' || _name) IN (d.photo_url, d.dl_url)
    ) OR (
      public.is_customer_of_driver(d.id)
      AND d.photo_url = 'storage://driver_kyc/' || _name
    )
  )
$$;
REVOKE ALL ON FUNCTION public.can_read_driver_file(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.can_read_driver_file(text) TO authenticated;

DROP POLICY IF EXISTS "kyc_driver_and_rider_read" ON storage.objects;
CREATE POLICY "kyc_driver_and_rider_read" ON storage.objects
  FOR SELECT TO authenticated
  USING (bucket_id = 'driver_kyc' AND public.can_read_driver_file(name));

-- S11 --------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.fleet_vehicles (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  plate_number text NOT NULL UNIQUE,
  model text NOT NULL DEFAULT 'Mahindra BE.6',
  color text NOT NULL DEFAULT 'Signature Orange',
  battery_percentage int NOT NULL DEFAULT 100 CHECK (battery_percentage BETWEEN 0 AND 100),
  status text NOT NULL DEFAULT 'in_bay' CHECK (status IN ('in_bay', 'assigned', 'maintenance')),
  assigned_driver_id uuid REFERENCES public.drivers(id) ON DELETE SET NULL,
  assigned_at timestamptz,
  bay_number text NOT NULL DEFAULT '',
  notes text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.fleet_vehicles ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "fleet_admin_all" ON public.fleet_vehicles;
CREATE POLICY "fleet_admin_all" ON public.fleet_vehicles FOR ALL TO authenticated
  USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
DROP POLICY IF EXISTS "fleet_driver_read_own" ON public.fleet_vehicles;
CREATE POLICY "fleet_driver_read_own" ON public.fleet_vehicles FOR SELECT TO authenticated
  USING (assigned_driver_id = public.current_active_driver_id());
